// Lưu custom names từ người dùng
class OutfitNameManager {
  constructor() {
    let userSuffix = '_guest';
    try {
      const user = JSON.parse(localStorage.getItem('currentUser'));
      if (user && user.username) userSuffix = `_${user.username}`;
    } catch (e) {}

    this.storageKey = `custom_outfit_names${userSuffix}`;
    this.customNames = this.loadCustomNames();
  }
  
  loadCustomNames() {
    const saved = localStorage.getItem(this.storageKey);
    return saved ? JSON.parse(saved) : {};
  }
  
  saveCustomNames() {
    localStorage.setItem(this.storageKey, JSON.stringify(this.customNames));
  }
  
  // Lấy tên outfit (ưu tiên custom name nếu có)
  getOutfitName(gender, event, index) {
    const key = `${gender}_${event}_${index}`;
    if (this.customNames[key]) {
      return this.customNames[key];
    }
    
    // Lấy từ database
    const db = outfitDatabase[gender]?.[event];
    if (db && db[index - 1]) {
      return db[index - 1].name;
    }
    
    return null;
  }
  
  // Lấy thông tin đầy đủ của outfit
  getOutfitInfo(gender, event, index) {
    const db = outfitDatabase[gender]?.[event];
    if (db && db[index - 1]) {
      const info = { ...db[index - 1] };
      // Override với custom name nếu có
      const customName = this.customNames[`${gender}_${event}_${index}`];
      if (customName) {
        info.name = customName;
        info.customized = true;
      }
      return info;
    }
    return null;
  }
  
  // Đặt tên mới cho outfit
  setOutfitName(gender, event, index, newName) {
    const key = `${gender}_${event}_${index}`;
    this.customNames[key] = newName;
    this.saveCustomNames();
  }
  
  // Reset tên về mặc định
  resetOutfitName(gender, event, index) {
    const key = `${gender}_${event}_${index}`;
    delete this.customNames[key];
    this.saveCustomNames();
  }
  
  // Reset tất cả custom names
  resetAllNames() {
    this.customNames = {};
    this.saveCustomNames();
  }
}

// Export
const outfitNameManager = new OutfitNameManager();
